-- G18: versioned, immutable generation contracts.
create table public.generation_contract_schema_versions(id uuid primary key default gen_random_uuid(),version text unique not null,json_schema jsonb not null,status text not null check(status in('draft','active','retired')),activated_at timestamptz,created_at timestamptz not null default now(),check((status='active')=(activated_at is not null)));
insert into public.generation_contract_schema_versions(version,json_schema,status,activated_at) values('1.0.0','{"required":["studentContext","releases","topic","content","difficulty","vocabulary","constructions","conjugation","competencies","concepts","courseContext","retrieval","questions","safety","retry","adminExplanation"]}','active',now());
create table public.generation_contracts(id uuid primary key default gen_random_uuid(),contract_key text unique not null,schema_version_id uuid not null references public.generation_contract_schema_versions(id) on delete restrict,student_id uuid not null references public.students(id) on delete cascade,target_decision_id uuid not null references public.student_target_decisions(id) on delete restrict,taxonomy_release_id uuid not null references public.taxonomy_releases(id) on delete restrict,lexical_release_id uuid not null references public.lexical_releases(id) on delete restrict,contract_payload jsonb not null,payload_checksum text not null,admin_explanation jsonb not null,created_at timestamptz not null default now(),unique(schema_version_id,payload_checksum));
create or replace function public.prevent_generation_contract_mutation()returns trigger language plpgsql as $$begin raise exception 'generation_contract_is_immutable';end$$;create trigger immutable_generation_contract before update or delete on public.generation_contracts for each row execute function public.prevent_generation_contract_mutation();
alter table public.generation_contract_schema_versions enable row level security;alter table public.generation_contracts enable row level security;create policy contract_schema_read on public.generation_contract_schema_versions for select using(status='active' or public.is_platform_admin());create policy generation_contract_read on public.generation_contracts for select using(public.can_view_student(student_id));grant select on public.generation_contract_schema_versions,public.generation_contracts to authenticated;
comment on table public.generation_contracts is 'Immutable deterministic interface saved before generation and pinned to exact taxonomy, lexical, resolver, and schema versions.';
